    "content": "文 | 刘凌果&nbsp; 编辑 | 海若镜 36氪获悉，脑科学AI公司曦嘉医疗近日完成数千万元Pre-A轮融资，由国中资本领投，锡创投、勤智资本、慧创医疗、兴富资本跟投。本轮融资主要用于临床研究、市场拓展和产品迭代。 曦嘉医疗成立于2019年，专注于通过AI、云计算技术，结合脑连接组学，解析MRI（磁共振成像）数据，从而为患者生成精准、个体化的脑网络图谱。目前，该项技术主要用于神经外科手术规划、神经调控和脑机接口电极植入前定位。 2025年5月，曦嘉医疗对外披露一笔数千万元天使轮融资，由险峰淇云投资，主要用于AI…"
