    "description": "今年的国庆假期是10月1日到7日，根据火车票预售期15天的规则，今天就可以购买国庆假期首日的火车票了。今年中秋假期与国庆假期时间接近，两节临近也带动机票、酒店的预订量上涨。平台数据显示，截至9月16日，“中秋”“国庆”等关键词搜索量环比上月增长167%，本周国庆机票酒店预订量环比上周增长56%，热门2000公里以上航线预订量同比翻番。这个假期大家都计划去哪儿？出游消费又将呈现出哪些新变化、新趋势？",
