    "author": "李元昊,张玉洁,戴斌",
    "description": "9月16日，马达加斯加总理拉乔纳里松·马米蒂亚纳走进武陵山脉腹地的湘西土家族苗族自治州花垣县十八洞村，探寻中国精准扶贫的“密码”。在十八洞村精准扶贫主题陈列馆内，他驻足细看、认真聆听，随后与村干部、村民面对面亲切交流。拉乔纳里松表示，希望将中国精准扶贫的成功经验借鉴推广到马达加斯加。（记者：张玉洁、戴斌；视频：李元昊）",
    "content": "9月16日，马达加斯加总理拉乔纳里松·马米蒂亚纳走进武陵山脉腹地的湘西土家族苗族自治州花垣县十八洞村，探寻中国精准扶贫的“密码”。在十八洞村精准扶贫主题陈列馆内，他驻足细看、认真聆听，随后与村干部、村民面对面亲切交流。拉乔纳里松表示，希望将中国精准扶贫的成功经验借鉴推广到马达加斯加。（记者：张玉洁、戴斌；视频：李元昊）"
