    "content": "遭让二追三，曼联联赛杯一轮游 北京时间9月17日凌晨，英格兰联赛杯第三轮上演一场逆转好戏。曼联在开场10分钟便取得两球领先的大好局面下，最终以2比3惨遭布莱顿逆转，连续第二个赛季在联赛杯首场比赛中便遭淘汰。 比赛开局堪称梦幻。第8分钟，小将莱西右路内切后左脚抽射破门，为曼联首开纪录。仅仅两分钟后，拉什福德断球后小角度打门被扑，芒特及时跟进补射入网，将比分扩大为2比0。此时的老特拉福德一片欢腾，似乎一场轻松的胜利已在囊中。 然而，曼联的崩盘来得毫无征兆。上半场补时阶段，布莱顿由科斯托拉斯扳回一城。 易边再战，红魔防线…"
