    "content": "走出丹阳高铁站南出站口，迎面就是“中国丹阳眼镜城”“中国丹阳国际眼镜城”。两个硕大的广告牌格外醒目，与高铁站仅一路之隔。从高铁站走到眼镜城，不过几分钟路程，沿街店铺挂着各色验光招牌，来自天南海北的游客背着包进店，开口第一句往往是：“配一副眼镜多少钱？” 江苏丹阳，一个人口不足百万的县级市，却是世界最大的眼镜镜片生产基地，年产镜片4亿余副，约占全国总产量的3/4、全球总产量的一半。而丹阳国际眼镜城则是全国最大的眼镜批发市场，2025年交易额超70亿元。 在无限风光的背后，丹阳眼镜产业的发展并非一片坦途。过去，长期依赖…"
