    "description": "16/09/2026 - 23:12 九十年代为争取科索沃从塞尔维亚独立而发动武装斗争的科索沃前总统塔其，因犯下谋杀、酷刑、非法拘禁等战争罪而于周三被海牙国际法庭判处25年徒刑。 该法庭合议庭裁定，科索沃解放军（UCK）前政治领导人塔其在1998年和1999年与塞尔维亚军队交战期间及战后犯有“非法逮捕、酷刑、谋杀和残忍对待”等罪行。 现年58岁的塔奇身着深色西装、白色衬衫和领带，面无表情地聆听了判决。 科索沃外长孔尤夫卡在法庭外向媒体表…",
    "content": "16/09/2026 - 23:12 九十年代为争取科索沃从塞尔维亚独立而发动武装斗争的科索沃前总统塔其，因犯下谋杀、酷刑、非法拘禁等战争罪而于周三被海牙国际法庭判处25年徒刑。 该法庭合议庭裁定，科索沃解放军（UCK）前政治领导人塔其在1998年和1999年与塞尔维亚军队交战期间及战后犯有“非法逮捕、酷刑、谋杀和残忍对待”等罪行。 现年58岁的塔奇身着深色西装、白色衬衫和领带，面无表情地聆听了判决。 科索沃外长孔尤夫卡在法庭外向媒体表示 “这对科索沃、对我们的解放战争来说是一个可怕的判决。这是一个令人悲伤、不公正…"
