    "content": "9月16日，在美国首都华盛顿，美国联邦储备委员会主席凯文·沃什出席记者会。新华社记者 李睿 摄 新华社纽约9月16日电（记者刘亚南 徐静）美国联邦储备委员会16日结束为期两天的货币政策会议，宣布将联邦基金利率目标区间上调25个基点，到3.75%至4%。 联邦公开市场委员会当日一致同意加息的决定符合市场此前预期，为2023年7月底以来美联储首次加息。 美联储在声明中表示，通胀依然高企，当日的货币政策决定将为通胀更快回落到联邦公开市场委员会2%的目标提供支持。 近期能源价格上涨和美国国债收益率走高让美联储面临显著压力，…"
