    "content": "新华社联合国9月16日电（记者吉黎）中国常驻联合国代表团临时代办孙磊15日在安理会也门问题紧急公开会上发言，呼吁各方保持冷静克制，立即停火止战，避免采取加剧紧张局势的行动，早日重返外交谈判的正确轨道。 孙磊说，也门、曼德海峡及周边地区形势近日又发生新的重大变化。也门政府和胡塞武装大规模战斗仍在持续，曼德海峡战略岛屿实控权发生转移，沙特重要输油管道遭到无人机袭击，冲突矛盾愈演愈烈。中方对冲突快速持续升级深表担忧。中方始终支持维护也门和沙特的主权、安全和领土完整，坚决反对在武装冲突中袭击包括能源在内的民用基础设施，强调…"
