    "description": "新华社波哥大9月16日电（记者李子健）哥伦比亚总统德拉埃斯普列亚16日在社交媒体上确认，13日在哥境内失联的小型飞机已被找到，机上5人全部遇难。 德拉埃斯普列亚表示，当局已确认机上人员被发现时均已没有生命迹象。他向遇难者亲属致以慰问。 哥伦比亚民航局13日通报，一架载有5人的小型飞机当天上午在该国境内失联并触发紧急求救信号，相关部门紧急启动搜救程序。通报显示，该飞机型号为塞斯纳T206，执飞哥伦比亚民事空中巡逻队相关任务。13日上午，飞…",
    "content": "新华社波哥大9月16日电（记者李子健）哥伦比亚总统德拉埃斯普列亚16日在社交媒体上确认，13日在哥境内失联的小型飞机已被找到，机上5人全部遇难。 德拉埃斯普列亚表示，当局已确认机上人员被发现时均已没有生命迹象。他向遇难者亲属致以慰问。 哥伦比亚民航局13日通报，一架载有5人的小型飞机当天上午在该国境内失联并触发紧急求救信号，相关部门紧急启动搜救程序。通报显示，该飞机型号为塞斯纳T206，执飞哥伦比亚民事空中巡逻队相关任务。13日上午，飞机从该国西部乔科省起飞，原定飞往首都波哥大附近一机场，9时23分与地面完成最后一…"
