    "content": "16/09/2026 - 17:33 欧盟委员会主席乌尔苏拉·冯德莱恩周三表示，欧盟将采取一切可能的手段来减少其与中国之间“不可持续的”贸易逆差。 欧盟正致力于缩减其对华巨额贸易逆差，该逆差被归咎于北京方面的不公平贸易行为。欧盟委员会主席乌尔苏拉·冯·德莱恩周三警告称，欧盟将动用一切可用的“手段”来实现这一目标。 欧盟委员会主席在欧洲议会开议首日发表的欧洲状况演讲中表示：“我们将动用一切可用的手段来重塑欧中双方关系的平衡。谈谈固然很好，但采取行动更好”。 这位欧盟执行机构负责人指出，“我们目前对华贸易逆差高达每天1…"
