    "content": "lsmod | grep -iE 'nvidia|nouveau' lspci -nnk | grep -A3 -E 'VGA|3D|Display' cat /etc/modprobe.d/nvidia.conf 看一下输出有nvidia吗，顺便nvidia-smi看一下有niri吗"
