    "description": "新华社约翰内斯堡9月16日电（记者靳博文）南非国际关系与合作部16日发布声明，对美国日前宣布针对南非有关人员实施新的签证限制措施表示关切，称美方曲解南非国内政策。 南非国际关系与合作部长罗纳德·拉莫拉在声明中说，美方有关举措再次迎合了特定团体对南非国内政策的错误描述，这些团体错误地将自身描绘成南非“少数群体”和阿非利卡人的代表。他说，作为主权国家，南非有权制定法律解决几百年来种族不公造成的问题。 针对有关南非犯罪具有种族针对性的说法，拉…",
    "content": "新华社约翰内斯堡9月16日电（记者靳博文）南非国际关系与合作部16日发布声明，对美国日前宣布针对南非有关人员实施新的签证限制措施表示关切，称美方曲解南非国内政策。 南非国际关系与合作部长罗纳德·拉莫拉在声明中说，美方有关举措再次迎合了特定团体对南非国内政策的错误描述，这些团体错误地将自身描绘成南非“少数群体”和阿非利卡人的代表。他说，作为主权国家，南非有权制定法律解决几百年来种族不公造成的问题。 针对有关南非犯罪具有种族针对性的说法，拉莫拉予以否认，表示犯罪影响所有南非人，并非针对基于种族、肤色或社会出身的特定群体…"
