    "content": "新华社南宁9月16日电 记者手记：江海之门开启时 新华社记者叶昊鸣、黄凯莹、杨驰 九月中旬的广西北部湾，海风裹着湿润的气息掠过钦州港。自港区向北望去，一条崭新宽阔的人工运河蜿蜒而来。西南内陆的江河，在今天与这片辽阔海域紧紧连在了一起。 2026年9月16日，历时4年建设的世纪工程平陆运河，正式通航。 上午，马道枢纽，汽笛划过长空，首航船舶缓缓驶过巨型闸门。不多时，消息传到钦州港，广西北部湾国际集装箱码头有限公司操作部经理凌国华低声说了一句：“江海真的通了。” 这不是一句简单的感慨。作为在钦州港工作多年的老港口人，凌…"
